'use client';

import { useRef, type CSSProperties } from 'react';
import { usePlayback } from './use-playback';
import './kaleidoscope-tiles.css';

export interface KaleidoscopeTilesProps {
  /** Mirrored wedges around the circle (an even number from 4 to 16). */
  segments?: number;
  paused?: boolean;
  size?: number;
  className?: string;
}

/**
 * A few original shapes drawn in one wedge, mirrored into every other wedge,
 * with the shapes turning slowly inside. Decorative only. Paused, off screen,
 * hidden or with reduced motion it shows the still pattern.
 */
export function KaleidoscopeTiles({
  segments = 8,
  paused = false,
  size = 200,
  className = '',
}: KaleidoscopeTilesProps) {
  const root = useRef<HTMLDivElement>(null);
  const playing = usePlayback(root, paused);
  const n = Math.max(4, Math.min(16, Math.round(segments / 2) * 2));
  const angle = 360 / n;
  const half = (angle / 2) * (Math.PI / 180);
  // The wedge, as a clip path from the center out to the edge.
  const wedge = `polygon(50% 50%, ${50 + 60 * Math.sin(-half)}% ${50 - 60 * Math.cos(half)}%, ${50 + 60 * Math.sin(half)}% ${50 - 60 * Math.cos(half)}%)`;

  return (
    <div
      ref={root}
      className={`mg-kaleido ${className}`}
      data-playing={playing}
      style={{ width: size, height: size } as CSSProperties}
      aria-hidden='true'
    >
      {Array.from({ length: n }, (_, i) => (
        <div
          key={i}
          className='mg-kaleido__wedge'
          style={{
            transform: `rotate(${i * angle}deg) scaleX(${i % 2 ? -1 : 1})`,
            clipPath: wedge,
          }}
        >
          <div className='mg-kaleido__shapes'>
            <span className='mg-kaleido__a' />
            <span className='mg-kaleido__b' />
            <span className='mg-kaleido__c' />
          </div>
        </div>
      ))}
    </div>
  );
}

.mg-kaleido {
  position: relative;
  overflow: hidden;
  border-radius: 50%;
  background: var(--mg-raised, #262626);
}

.mg-kaleido__wedge {
  position: absolute;
  inset: 0;
}

.mg-kaleido__shapes {
  position: absolute;
  inset: 0;
  animation: mg-kaleido-turn 18s linear infinite;
  animation-play-state: paused;
}

.mg-kaleido[data-playing='true'] .mg-kaleido__shapes {
  animation-play-state: running;
}

.mg-kaleido__shapes > span {
  position: absolute;
}

.mg-kaleido__a {
  top: 14%;
  left: 44%;
  width: 22%;
  height: 22%;
  border-radius: 50%;
  background: var(--mg-accent, #eaf2fb);
}

.mg-kaleido__b {
  top: 30%;
  left: 36%;
  width: 14%;
  height: 14%;
  background: var(--mg-accent, #eaf2fb);
  transform: rotate(45deg);
}

.mg-kaleido__c {
  top: 4%;
  left: 52%;
  width: 6%;
  height: 30%;
  border-radius: 3px;
  background: #dce9f7;
}

@keyframes mg-kaleido-turn {
  to {
    transform: rotate(1turn);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-kaleido__shapes {
    animation: none;
  }
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}
